const RUNTIME_VERSION = 'shared-current-v10-runtime/v1';
const PATTERN_ENTRY_VERSION = 'paper-pattern-entry/v10';
const MANILA_OFFSET_MS = 8 * 60 * 60 * 1000;

type Category = 'candidates' | 'waiting' | 'conflicts';

export type LatestV10AnalysisPresentation =
  | { available: false; reason: 'MISSING' | 'INVALID' | 'FUTURE' | 'STALE_RUNTIME' }
  | {
      available: true;
      timestampSemantics: 'ANALYSIS_EVALUATED_AT';
      evaluatedAt: number;
      manilaDay: string;
      scope: 'LATEST_ANALYSIS_SNAPSHOT';
      counts: Record<Category, number>;
      reasons: { category: 'waiting' | 'conflicts'; reason: string; count: number }[];
      limitations: {
        dailyTotalsAvailable: false;
        lifecycleTotalsAvailable: false;
        pnlAvailable: false;
        candidatesAreOrdersOrFills: false;
      };
    };

function record(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null;
}

function nonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

function finiteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function stringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every(nonEmptyString);
}

function candidateIdentity(value: unknown): string | null {
  const row = record(value);
  if (!row || !nonEmptyString(row.eventId) || !nonEmptyString(row.durableFormationId)
    || !nonEmptyString(row.symbol) || !nonEmptyString(row.patternId)
    || !['15m', '1h', '4h'].includes(String(row.timeframe))
    || !['LONG', 'SHORT'].includes(String(row.direction))
    || !finiteNumber(row.formationAt) || row.formationAt <= 0
    || !finiteNumber(row.confirmedAt) || !finiteNumber(row.triggerPrice)
    || !finiteNumber(row.referencePrice) || !finiteNumber(row.stopPrice)) return null;
  return JSON.stringify([row.eventId, row.durableFormationId, row.symbol, row.patternId,
    row.timeframe, row.direction, row.formationAt]);
}

function waitingIdentity(value: unknown): { identity: string; reason: string } | null {
  const row = record(value);
  if (!row || !nonEmptyString(row.symbol) || !nonEmptyString(row.eventId)
    || !nonEmptyString(row.patternId) || !nonEmptyString(row.timeframe)
    || !finiteNumber(row.formationAt) || !nonEmptyString(row.reason)) return null;
  return { identity: JSON.stringify([row.symbol, row.eventId, row.patternId, row.timeframe,
    row.formationAt, row.reason]), reason: row.reason };
}

function conflictIdentity(value: unknown): { identity: string; reason: string } | null {
  const row = record(value);
  if (!row || !nonEmptyString(row.symbol) || !nonEmptyString(row.eventId)
    || !nonEmptyString(row.timeframe) || !finiteNumber(row.formationAt)
    || !nonEmptyString(row.reason) || !stringArray(row.longPatternIds)
    || !stringArray(row.shortPatternIds)) return null;
  return { identity: JSON.stringify([row.symbol, row.eventId, row.timeframe, row.formationAt,
    row.reason, row.longPatternIds, row.shortPatternIds]), reason: row.reason };
}

function unavailable(reason: 'MISSING' | 'INVALID' | 'FUTURE' | 'STALE_RUNTIME') {
  return { available: false as const, reason };
}

/** Pure display validation. It never infers daily trades, lifecycle events, PnL, or completion. */
export function presentLatestV10Analysis(
  input: unknown,
  options: { nowMs: number; runtimeMaxAgeMs: number },
): LatestV10AnalysisPresentation {
  if (!Number.isSafeInteger(options.nowMs) || !Number.isSafeInteger(options.runtimeMaxAgeMs)
    || options.nowMs <= 0 || options.runtimeMaxAgeMs < 0) return unavailable('INVALID');
  const runtime = record(input);
  if (!runtime) return unavailable('MISSING');
  if (runtime.version !== RUNTIME_VERSION || !nonEmptyString(runtime.at)) return unavailable('INVALID');
  const runtimeAt = Date.parse(runtime.at);
  if (!Number.isFinite(runtimeAt) || runtimeAt <= 0) return unavailable('INVALID');
  if (runtimeAt > options.nowMs) return unavailable('FUTURE');
  if (options.nowMs - runtimeAt > options.runtimeMaxAgeMs) return unavailable('STALE_RUNTIME');

  const snapshot = record(runtime.patternEntries);
  if (!snapshot) return unavailable('MISSING');
  const evaluatedAt = snapshot.evaluatedAt;
  if (snapshot.version !== PATTERN_ENTRY_VERSION || !finiteNumber(evaluatedAt) || !Number.isSafeInteger(evaluatedAt)
    || evaluatedAt <= 0 || !Number.isFinite(new Date(evaluatedAt).getTime())) return unavailable('INVALID');
  if (evaluatedAt > options.nowMs || evaluatedAt > runtimeAt) return unavailable('FUTURE');
  if (!Array.isArray(snapshot.candidates) || !Array.isArray(snapshot.waiting)
    || !Array.isArray(snapshot.conflicts)) return unavailable('INVALID');

  const candidates = snapshot.candidates.map(candidateIdentity);
  const waiting = snapshot.waiting.map(waitingIdentity);
  const conflicts = snapshot.conflicts.map(conflictIdentity);
  if (candidates.some(x => x === null) || waiting.some(x => x === null)
    || conflicts.some(x => x === null)) return unavailable('INVALID');

  const candidateIds = new Set(candidates as string[]);
  const waitingRows = [...new Map((waiting as { identity: string; reason: string }[])
    .map(row => [row.identity, row])).values()];
  const conflictRows = [...new Map((conflicts as { identity: string; reason: string }[])
    .map(row => [row.identity, row])).values()];
  const reasonCounts = new Map<string, { category: 'waiting' | 'conflicts'; reason: string; count: number }>();
  for (const [category, rows] of [['waiting', waitingRows], ['conflicts', conflictRows]] as const) {
    for (const row of rows) {
      const key = `${category}\0${row.reason}`;
      const previous = reasonCounts.get(key);
      reasonCounts.set(key, { category, reason: row.reason, count: (previous?.count ?? 0) + 1 });
    }
  }

  const manilaTime = evaluatedAt + MANILA_OFFSET_MS;
  if (!Number.isSafeInteger(manilaTime) || !Number.isFinite(new Date(manilaTime).getTime())) return unavailable('INVALID');
  return {
    available: true,
    timestampSemantics: 'ANALYSIS_EVALUATED_AT',
    evaluatedAt,
    manilaDay: new Date(manilaTime).toISOString().slice(0, 10),
    scope: 'LATEST_ANALYSIS_SNAPSHOT',
    counts: { candidates: candidateIds.size, waiting: waitingRows.length, conflicts: conflictRows.length },
    reasons: [...reasonCounts.values()],
    limitations: {
      dailyTotalsAvailable: false,
      lifecycleTotalsAvailable: false,
      pnlAvailable: false,
      candidatesAreOrdersOrFills: false,
    },
  };
}

import { describe, expect, it } from 'vitest';
import { presentLatestV10Analysis } from '../latestV10AnalysisPresentation';

const evaluatedAt = Date.parse('2026-10-30T15:59:59.000Z');
const nowMs = Date.parse('2026-10-30T16:10:00.000Z');
const base = {
  version: 'shared-current-v10-runtime/v1',
  at: '2026-10-30T16:09:00.000Z',
  patternEntries: { version: 'paper-pattern-entry/v10', evaluatedAt, candidates: [], waiting: [], conflicts: [] },
};
const options = { nowMs, runtimeMaxAgeMs: 5 * 60_000 };

describe('latest V10 analysis presentation', () => {
  it('uses evaluatedAt rather than a later polling timestamp and assigns the Manila day', () => {
    const result = presentLatestV10Analysis(base, options);
    expect(result).toMatchObject({ available: true, evaluatedAt, manilaDay: '2026-10-30' });
    expect(result.available && result.evaluatedAt).not.toBe(Date.parse(base.at));
  });

  it('handles the Manila boundary without using the UTC day', () => {
    const result = presentLatestV10Analysis({ ...base, patternEntries: { ...base.patternEntries,
      evaluatedAt: Date.parse('2026-10-30T16:00:00.000Z') } }, options);
    expect(result).toMatchObject({ available: true, manilaDay: '2026-10-31' });
  });

  it('distinguishes a validated empty latest snapshot from unavailable evidence', () => {
    expect(presentLatestV10Analysis(base, options)).toMatchObject({
      available: true, scope: 'LATEST_ANALYSIS_SNAPSHOT', counts: { candidates: 0, waiting: 0, conflicts: 0 },
      limitations: { dailyTotalsAvailable: false, lifecycleTotalsAvailable: false, pnlAvailable: false },
    });
    expect(presentLatestV10Analysis({}, options)).toEqual({ available: false, reason: 'INVALID' });
    expect(presentLatestV10Analysis({ ...base, patternEntries: null }, options)).toEqual({ available: false, reason: 'MISSING' });
  });

  it.each([
    [{ ...base, at: 'not-a-date' }, 'INVALID'],
    [{ ...base, at: '2026-10-30T16:11:00.000Z' }, 'FUTURE'],
    [{ ...base, at: '2026-10-30T16:00:00.000Z' }, 'STALE_RUNTIME'],
    [{ ...base, patternEntries: { ...base.patternEntries, evaluatedAt: nowMs + 1 } }, 'FUTURE'],
    [{ ...base, patternEntries: { ...base.patternEntries, evaluatedAt: null } }, 'INVALID'],
    [base, 'INVALID', { nowMs: Number.NaN, runtimeMaxAgeMs: 1 }],
    [base, 'INVALID', { nowMs, runtimeMaxAgeMs: -1 }],
    [{ ...base, patternEntries: { ...base.patternEntries, evaluatedAt: 0 } }, 'INVALID'],
    [{ ...base, at: '+275760-09-13T00:00:00.000Z', patternEntries: { ...base.patternEntries,
      evaluatedAt: 8_640_000_000_000_000 } }, 'INVALID', { nowMs: 8_640_000_000_000_000, runtimeMaxAgeMs: 0 }],
  ])('fails closed for invalid, future, missing, or stale evidence', (input, reason, customOptions) => {
    expect(presentLatestV10Analysis(input, customOptions ?? options)).toEqual({ available: false, reason });
  });

  it('does not throw when the Manila offset exceeds the Date range', () => {
    const input = { ...base, at: '+275760-09-13T00:00:00.000Z', patternEntries: { ...base.patternEntries,
      evaluatedAt: 8_640_000_000_000_000 } };
    const edge = { nowMs: 8_640_000_000_000_000, runtimeMaxAgeMs: 0 };
    expect(() => presentLatestV10Analysis(input, edge)).not.toThrow();
    expect(presentLatestV10Analysis(input, edge)).toEqual({ available: false, reason: 'INVALID' });
  });

  it('counts and deduplicates valid candidates without treating overlapping categories as events', () => {
    const candidate = { eventId: 'e1', durableFormationId: 'f1', symbol: 'BTC', patternId: 'p1',
      timeframe: '15m', direction: 'LONG', formationAt: 1, confirmedAt: 2, triggerPrice: 3,
      referencePrice: 3, stopPrice: 2 };
    const waiting = { symbol: 'BTC', eventId: 'e1', patternId: 'p1', timeframe: '15m', formationAt: 1, reason: 'WAIT' };
    const result = presentLatestV10Analysis({ ...base, patternEntries: { ...base.patternEntries,
      candidates: [candidate, candidate], waiting: [waiting] } }, options);
    expect(result).toMatchObject({ available: true, counts: { candidates: 1, waiting: 1, conflicts: 0 } });
    expect(result.available && result.scope).toBe('LATEST_ANALYSIS_SNAPSHOT');
  });

  it('deduplicates exact identities and rejects malformed rows instead of producing false zero', () => {
    const waiting = { symbol: 'BTC', eventId: 'e1', patternId: 'p1', timeframe: '15m', formationAt: 1, reason: 'WAIT' };
    const conflict = { symbol: 'BTC', eventId: 'e2', timeframe: '1h', formationAt: 2,
      reason: 'CONFLICT', longPatternIds: ['long'], shortPatternIds: ['short'] };
    const result = presentLatestV10Analysis({ ...base, patternEntries: { ...base.patternEntries,
      waiting: [waiting, waiting], conflicts: [conflict, conflict] } }, options);
    expect(result).toMatchObject({ available: true, counts: { candidates: 0, waiting: 1, conflicts: 1 } });
    expect(result.available && result.reasons).toEqual([
      { category: 'waiting', reason: 'WAIT', count: 1 },
      { category: 'conflicts', reason: 'CONFLICT', count: 1 },
    ]);
    expect(presentLatestV10Analysis({ ...base, patternEntries: { ...base.patternEntries,
      waiting: [{ symbol: 'BTC' }] } }, options)).toEqual({ available: false, reason: 'INVALID' });
  });
});

import { useState } from 'react';
import { hasSharedMarginRuntime } from '@/lib/sharedMarginReadback';
import { CalendarDays, ChevronLeft, ChevronRight } from 'lucide-react';
import { useVirtualPaper400 } from '@/lib/context/VirtualPaper400Context';
import { amount, timestamp } from '@/lib/virtual400Presentation';
import { calendarMonthCells, calendarScopeLabels, shiftCalendarMonth } from '@/lib/paperCalendar';
import { presentLatestV10Analysis } from '@/lib/latestV10AnalysisPresentation';
import { V10LatestSnapshotPanel } from '@/components/presentation/V10AnalysisEvidence';

export default function CalendarPage() {
  const { data, fresh, error, now } = useVirtualPaper400();
  const ordinaryCloseOnly = hasSharedMarginRuntime(data?.runtime);
  const labels = calendarScopeLabels(ordinaryCloseOnly);
  const calendar = fresh && data?.runtime?.calendar?.status === 'AVAILABLE' ? data.runtime.calendar : null;
  const v10 = fresh ? presentLatestV10Analysis(data?.runtime, { nowMs: now, runtimeMaxAgeMs: 5 * 60_000 }) : { available: false as const, reason: 'STALE_RUNTIME' as const };
  const currentMonth = calendar?.throughDate?.slice(0,7) ?? '';
  const firstMonth = calendar?.coverageStart?.slice(0,7) ?? '';
  const [requestedMonth, setMonth] = useState('');
  const [selected, setSelected] = useState<string | null>(null);
  const month = currentMonth ? (requestedMonth >= firstMonth && requestedMonth <= currentMonth ? requestedMonth : currentMonth) : '';
  const cells = calendarMonthCells(month);
  const byDate = new Map(calendar?.days.map(day => [day.date,day]) ?? []);
  const summary = (calendar?.days ?? []).filter(day => day.date.startsWith(month)).reduce((a,d) => ({net:a.net+d.netPnlUsd,entries:a.entries+d.entries,completed:a.completed+d.completedTrades}),{net:0,entries:0,completed:0});
  const selectedDay = selected ? byDate.get(selected) : undefined;
  const tone = (n: number) => n > 0 ? 'is-profit' : n < 0 ? 'is-loss' : 'is-flat';
  function move(delta: number) { setMonth(shiftCalendarMonth(month,delta)); setSelected(null); }
  return <div className="space-y-6">
    <div className="ccc-page-heading"><div><p className="ccc-eyebrow">PAPER · PNL CALENDAR</p><h1>수익 달력</h1><p>{labels.pageDescription}</p></div><span className="ccc-paper-tag">필리핀 시간 · PHT</span></div>
    {ordinaryCloseOnly && <p className="ccc-callout" data-testid="shared-margin-calendar-scope">일반 CLOSE 회계 범위의 달력입니다. V10 관측·typed terminal·별도 PAPER 모형은 손익과 거래 횟수에서 제외되며, 일반 거래 0건은 V10 활동 없음이라는 뜻이 아닙니다.</p>}
    <V10LatestSnapshotPanel evidence={v10} evaluatedLabel={v10.available ? `${timestamp(new Date(v10.evaluatedAt).toISOString())} PHT` : undefined} selectedDay={selected} />
    {!calendar ? <section className="ccc-panel"><div className="ccc-empty-row" role="status"><CalendarDays size={24}/><div><strong>{ordinaryCloseOnly ? '일반 CLOSE 수익 달력 확인 대기' : '수익 달력 확인 대기'}</strong><p>{error || '서버의 거래 기록을 확인하고 있습니다. 미확인 값을 0으로 표시하지 않습니다.'}</p></div></div></section> : <section className="ccc-panel ccc-calendar" aria-label={labels.aria}>
      <header className="ccc-panel-heading"><div><p className="ccc-eyebrow">{labels.eyebrow}</p><h2 aria-live="polite">{month.slice(0,4)}년 {Number(month.slice(5))}월</h2></div><div className="ccc-calendar-controls"><button className="ccc-icon-button" aria-label="이전 달" disabled={month <= firstMonth} onClick={()=>move(-1)}><ChevronLeft size={18}/></button><button className="ccc-select" disabled={month === currentMonth} onClick={()=>{setMonth(currentMonth);setSelected(null);}}>이번 달</button><button className="ccc-icon-button" aria-label="다음 달" disabled={month >= currentMonth} onClick={()=>move(1)}><ChevronRight size={18}/></button></div></header>
      <div className="ccc-calendar-summary"><div><span>{labels.net}</span><strong className={summary.net<0?'ccc-negative':summary.net>0?'ccc-positive':''}>{amount(summary.net,true)} <small>USDC</small></strong></div><div><span>{labels.entries}</span><strong>{summary.entries}<small>회</small></strong></div><div><span>{labels.completed}</span><strong>{summary.completed}<small>건</small></strong></div></div>
      <div className="ccc-calendar-scroll" tabIndex={0} role="region" aria-label={`${ordinaryCloseOnly ? '일반 CLOSE ' : ''}수익 달력 · 가로 스크롤`}><table className="ccc-calendar-table"><caption className="sr-only">{month} {ordinaryCloseOnly ? '일반 거래의 일별 비용 차감 순손익, 진입과 CLOSE 완료 횟수' : '일별 비용 차감 순손익, 진입과 청산 완료 횟수'}</caption><thead><tr>{['일','월','화','수','목','금','토'].map(d=><th scope="col" key={d}>{d}</th>)}</tr></thead><tbody>{Array.from({length:cells.length/7},(_,week)=><tr key={week}>{cells.slice(week*7,week*7+7).map((date,i)=>{
        if(!date)return <td key={`blank-${i}`} className="ccc-calendar-blank"/>;
        const covered=date >= calendar.coverageStart! && date <= calendar.throughDate!;
        const day=byDate.get(date);const net=day?.netPnlUsd??0;const entries=day?.entries??0;const completed=day?.completedTrades??0;
        return <td key={date}><button disabled={!covered} aria-pressed={selected===date} aria-label={`${date} ${covered?`${ordinaryCloseOnly ? '일반 CLOSE ' : ''}순손익 ${amount(net,true)} USDC, ${labels.entries} ${entries}회, ${labels.completed} ${completed}건`:date>calendar.throughDate!?'예정':'기록 시작 전'}`} onClick={()=>setSelected(date)} className={`ccc-calendar-day ${covered?tone(net):'is-unavailable'} ${date===calendar.throughDate?'is-today':''}`}><span className="ccc-calendar-date">{Number(date.slice(8))}{date===calendar.throughDate&&<small>오늘 · 진행 중</small>}</span>{covered?<><strong>{amount(net,true)}<small>USDC</small></strong><span>{labels.entries} {entries} · {labels.completed} {completed}</span>{!day&&<small>{labels.empty}</small>}</>:<><strong>—</strong><small>{date>calendar.throughDate!?'예정':'기록 시작 전'}</small></>}</button></td>;
      })}</tr>)}</tbody></table></div>
      {selected && <div className="ccc-calendar-detail" aria-live="polite"><strong>{selected} {labels.detail}</strong><span>총손익 {amount(selectedDay?.grossPnlUsd??0,true)} USDC</span><span>추정 비용 {amount(selectedDay?.costUsd??0)} USDC</span><span>순손익 {amount(selectedDay?.netPnlUsd??0,true)} USDC</span><span>{ordinaryCloseOnly ? '일반 정산' : '정산'} {selectedDay?.settlements??0}건 · 부분청산 포함</span></div>}
      <footer className="ccc-panel-footer"><span>{ordinaryCloseOnly ? '일반 CLOSE 수익' : '수익'} + / 손실 − · 날짜를 선택하면 상세 표시</span><span>{timestamp(calendar.observedAt,true)} PHT 기준</span></footer>
      <p className="ccc-calendar-note">{calendar.coverageStart}부터 {ordinaryCloseOnly ? '현재 가상 세션의 일반 CLOSE 회계 범위만 집계합니다. V10 관측과 typed terminal은 포함하지 않습니다. 진입은 일반 포지션 개설, 완료는 일반 최종 CLOSE 기준입니다.' : '현재 가상 세션의 전체 원장을 집계합니다. 진입은 포지션 개설, 완료는 최종 청산 기준입니다.'} 부분청산 손익은 정산된 날짜에 반영하며, 추가 입금과 미실현 손익은 제외합니다.</p>
    </section>}
  </div>;
}

import { useVirtualPaper400 } from '@/lib/context/VirtualPaper400Context';
import { ACTIVITY_LABELS, activityPresentation, activityReason, parseLegacyActivityPrefix, parseLegacyActivityReason, type ActivityPhase } from '@/lib/virtualActivityPresentation';
import { timestamp } from '@/lib/virtual400Presentation';
import { presentLatestV10Analysis } from '@/lib/latestV10AnalysisPresentation';
import { AnalysisTimeEvidence } from '@/components/presentation/V10AnalysisEvidence';

const steps: { phase: ActivityPhase; label: string }[] = [
  { phase: 'CHECKING_ACCOUNT', label: '계정·보호 확인' }, { phase: 'CHECKING_COSTS', label: '거래 비용 확인' },
  { phase: 'ANALYZING_MARKETS', label: '확정 캔들·전략 분석' }, { phase: 'CHECKING_ENTRY', label: '위험·진입 판단' },
];
function ReceivedReason({ reason, label }: { reason: string; label: string }) {
  return <details className="ccc-ai-raw"><summary>{label}</summary><p>서버에서 수신된 원문입니다. 전체 기록의 일부일 수 있습니다.</p><pre>{reason}</pre></details>;
}
export function AiAnalysisActivity() {
  const { data, fresh, now } = useVirtualPaper400();
  const view = activityPresentation(data, fresh, now);
  const evaluation = fresh ? presentLatestV10Analysis(data?.runtime, { nowMs: now, runtimeMaxAgeMs: 5 * 60_000 }) : { available: false as const, reason: 'STALE_RUNTIME' as const };
  const observed = new Set(view.activity?.events.map(e => e.phase) ?? []);
  const conclusion = view.phase === 'STOPPED' ? '신규 진입 중지' : view.phase === 'BLOCKED' ? '신규 진입 차단' : view.phase === 'ERROR' ? '분석 상태 확인 필요' : '현재 상태';
  return <section className="ccc-panel ccc-ai-activity" aria-label="AI 분석 활동">
    <header className="ccc-ai-activity-heading"><div><p className="ccc-eyebrow">AI ACTIVITY</p><h2>AI 분석 활동</h2></div><span role="status" className={`ccc-ai-state is-${view.tone}`}><i aria-hidden="true" />{view.headline}</span></header>
    <div className={`ccc-ai-conclusion is-${view.tone}`}><strong>{conclusion}</strong><p className="ccc-ai-summary">{view.reason}</p>{view.activity?.reason && <ReceivedReason reason={view.activity.reason} label="상태 원문 확인" />}</div>
    <div><ol className="ccc-ai-stages" aria-label="이번 서버 주기에서 관측한 단계">{steps.map((step, i) => { const current = view.live && view.phase === step.phase; const recorded = observed.has(step.phase); return <li key={step.phase} className={current ? 'is-current' : recorded ? 'is-observed' : 'is-unobserved'} aria-current={current ? 'step' : undefined}><b className="ccc-ai-step-number" aria-hidden="true">{i + 1}</b><span>{step.label}</span><small><i aria-hidden="true">{current ? '◉' : recorded ? '●' : '○'}</i>{current ? '진행 중' : recorded ? '관측됨' : '미관측'}</small></li>; })}</ol><p className="ccc-ai-stage-note">관측됨은 서버에 단계 기록이 있다는 뜻입니다. 통과·완료를 뜻하지 않으며, 미관측은 실패가 아닙니다.</p></div>
    {view.symbols.length > 0 ? <div className="ccc-ai-symbols">{view.symbols.map(symbol => {
      const result = view.results.find(row => row.symbol === symbol); const parsed = result?.evaluated ? parseLegacyActivityReason(result.reason, symbol) : null; const reference = parsed ?? (result?.evaluated ? parseLegacyActivityPrefix(result.reason, symbol) : null); const active = view.live && view.activity?.symbols.includes(symbol);
